/** Delegated listener: on(root, 'click', '.sel', (e, match) => {}) — one listener per root. */
export function on(root, type, selector, handler, options) {
  const fn = (event) => {
    const match = selector ? event.target.closest(selector) : root;
    if (match && root.contains(match)) handler(event, match);
  };
  root.addEventListener(type, fn, options);
  return () => root.removeEventListener(type, fn, options);
}
/** CustomEvent bus on document (or a target). Names are namespaced: mhs:<component>:<event>. */
export function emit(name, detail = {}, target = document) {
  target.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
}
export function listen(name, handler, target = document) {
  target.addEventListener(name, handler);
  return () => target.removeEventListener(name, handler);
}
